UPDATE products SET name=#{name}, description=#{description}, price=#{price}, stock=#{stock},
    category_id=#{categoryId}, enabled=#{enabled}, updated_at=NOW()
WHERE id=#{id}

sql.where:

    AND (
    p.name LIKE CONCAT('%', #{params.keyword}, '%')
    OR p.description LIKE CONCAT('%', #{params.keyword}, '%')
    OR c.name LIKE CONCAT('%', #{params.keyword}, '%')
    )


    AND p.category_id = #{params.categoryId}


    AND p.price >= #{params.minPrice}


    AND p.price <= #{params.maxPrice}

AND (p.enabled = 1 OR p.enabled IS NULL)

mapper.select:
SELECT FROM products p LEFT JOIN product_category c ON p.category_id = c.category_id
ORDER BY p.price ASC ORDER BY p.price DESC ORDER BY p.sales_volume DESC, p.created_at DESC ORDER BY p.created_at DESC
LIMIT #{params.offset}, #{params.limit}

SELECT user_id as userId, rating, content, images, reply, status,
       created_at as createdAt, updated_at as updatedAt
FROM product_reviews WHERE product_id = #{productId}
ORDER BY created_at DESC LIMIT #{limit}
